 "content": "from collections import deque


def transform(grid):
    """Compact rigid, same-color connected objects toward a full 2-line."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The full line of 2s is the solid wall that attracts the objects.
    wall = None
    if any(all(v == 2 for v in row) for row in grid):
        wall = ("row", next(r for r, row in enumerate(grid) if all(v == 2 for v in row)))
    else:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                wall = ("col", c)
                break
    if wall is None:
        return out

    # Find rigid monochrome 4-connected components, excluding the wall.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append({"color": color, "cells": cells})

    kind, index = wall
    if kind == "row":
        dr = 1 if index == 0 else -1
        # Closest-to-wall objects settle first.
        if dr == 1:
            components.sort(key=lambda o: min(r for r, c in o["cells"]))
        else:
            components.sort(key=lambda o: -max(r for r, c in o["cells"]))
        dc = 0
    else:
        dc = 1 if index == 0 else -1
        if dc == 1:
            components.sort(key=lambda o: min(c for r, c in o["cells"]))
        else:
            components.sort(key=lambda o: -max(c for r, c in o["cells"]))
        dr = 0

    # Remove all objects, then drop each intact component until blocked.
    for obj in components:
        for r, c in obj["cells"]:
            out[r][c] = 0
    for obj in components:
        cells = obj["cells"]
        color = obj["color"]
        while True:
            moved = [(r + dr, c + dc) for r, c in cells]
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in moved):
                break
            if any(out[r][c] != 0 for r, c in moved):
                break
            cells = moved
        for r, c in cells:
            out[r][c] = color
    return out
